style.css:
@-moz-document domain("youtube.com") {
/* General Background */
  body {
    background-color: #f9f0ff !important; /* Lavender */
    color: #4b4b63 !important; /* Darker lavender for text */
  }

  /* Header and Top Navigation */
  #masthead-container {
    background-color: #e6ffe6 !important; /* Mint Green */
    color: #4b4b63 !important; /* Lavender Text */
  }

  /* Sidebar */
  #guide {
    background-color: #e6ffe6 !important; /* Mint Green */
    color: #4b4b63 !important;
  }

  /* Video Titles */
  #video-title {
    color: #4b4b63 !important; /* Dark lavender */
  }

  /* Buttons (Like, Subscribe, etc.) */
  .yt-spec-button-shape-next--solid {
    background-color: #e6ffe6 !important; /* Mint Green */
    color: #4b4b63 !important; /* Lavender text */
    border-radius: 8px !important; /* Rounded buttons */
    border: 1px solid #bdebbd !important; /* Subtle mint green border */
  }
  .yt-spec-button-shape-next--solid:hover {
    background-color: #d2ffd2 !important; /* Lighter mint green on hover */
  }

  /* Search Bar */
  #search-form {
    background-color: #f9f0ff !important; /* Lavender */
    border-radius: 12px !important;
    border: 1px solid #e0d7ff !important; /* Subtle lavender border */
  }

  /* Video Thumbnails */
  ytd-thumbnail {
    border-radius: 12px !important; /* Rounded thumbnails */
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1) !important; /* Soft shadow */
    background-color: #e6ffe6 !important; /* Mint Green */
  }

  /* Footer */
  #footer {
    background-color: #f9f0ff !important; /* Lavender */
    color: #4b4b63 !important;
  }
}
